effect.shader:
vec4 fxPortOutput;

vec4 fxPortSample(sampler2D image, vec2 uv) {
    vec4 color = texture2D(image, uv);
    if (color.a > 0.0) color.rgb /= color.a;
    else color.rgb = vec3(0.0);
    return color;
}

void fxPortMain() {
    vec2 uv = clamp(acScreenNorm, 0.0, 1.0);
    vec4 original = fxPortSample(inputImg.texture, uv);
    float amount = exp2(uControl2);
    vec2 q = uv - vec2(0.5);
    float sx = q.x < 0.0 ? uControl3 : uControl4;
    float sy = q.y > 0.0 ? uControl5 : uControl6;
    q.x *= exp2(0.5 * amount * sx);
    q.y *= exp2(0.5 * amount * sy);
    vec2 sheared = vec2(q.x + 0.25 * amount * uControl7 * q.y,
                        q.y + 0.25 * amount * uControl8 * q.x);
    vec2 mapped = sheared + vec2(0.5);
    float inside = step(0.0, mapped.x) * step(mapped.x, 1.0) *
                   step(0.0, mapped.y) * step(mapped.y, 1.0);
    vec4 sampled = fxPortSample(inputImg.texture, clamp(mapped, 0.0, 1.0));
    vec4 effected = sampled * inside;
    fxPortOutput = clamp(mix(original, effected,
                             clamp(uControl1, 0.0, 1.0)), 0.0, 1.0);
}

void main() {
    if (uControl1 <= 0.0) {
        gl_FragColor = texture2D(inputImg.texture, clamp(acScreenNorm, 0.0, 1.0));
        return;
    }
    fxPortMain();
    gl_FragColor = vec4(fxPortOutput.rgb * fxPortOutput.a, fxPortOutput.a);
}
